program.source:
Function impuesto <- Iva(precio As Integer)
  Define impuesto As Integer;
  Write "Calculando el IVA";
  impuesto <- precio * 21 Div 100;
EndFunction

Algorithm Principal
  Define precio As Integer;
  Read precio;
  Write "IVA: ", Iva(precio);
EndAlgorithm

